oxy_webhelp_navlinks = {"data_impact_investigation-d39307e53760":{"topics":[{"title":"Prerequisites and supported object types","shortdesc":"<p class=\"shortdesc\">Requirements for accessing data impact investigation and the workload types that         support the feature.<\/p>","href":"saas\/data_impact_prereq_object_types.html","attributes":{"data-id":"data_impact_prereq_object_types"},"menu":{"hasChildren":false},"tocID":"data_impact_prereq_object_types-d39307e53771","topics":[]},{"title":"Investigation dashboard","shortdesc":"<p class=\"shortdesc\">The Investigation dashboard lists all objects with <span class=\"ph\">Anomaly Detection<\/span> enabled and         their most recent file change activity, so administrators can quickly identify objects         impacted by a deletion or encryption event.<\/p>","href":"saas\/data_impact_investigation_dashboard.html","attributes":{"data-id":"data_impact_investigation_dashboard"},"menu":{"hasChildren":false},"tocID":"data_impact_investigation_dashboard-d39307e53782","topics":[]},{"title":"Individual object view","shortdesc":"<p class=\"shortdesc\">The individual object view shows file change activity for a single protected object         across backup snapshots. The Snapshot and File Activity tabs support investigation and recovery initiation at the         snapshot level and file level.<\/p>","href":"saas\/data_impact_individual_object_view.html","attributes":{"data-id":"data_impact_individual_object_view"},"menu":{"hasChildren":false},"tocID":"data_impact_individual_object_view-d39307e53796","topics":[]},{"title":"Mounting live objects from impacted snapshots","shortdesc":"<p class=\"shortdesc\">Recover a virtual machine affected by a deletion or encryption event using a live         mount to restore access while the data remains on the Rubrik cluster.<\/p>","href":"saas\/live_mounting_impacted_snapshots.html","attributes":{"data-id":"live_mounting_impacted_snapshots"},"menu":{"hasChildren":false},"tocID":"live_mounting_impacted_snapshots-d39307e53807","topics":[]},{"title":"Exporting objects from impacted snapshots","shortdesc":"<p class=\"shortdesc\">Recover a virtual machine affected by a deletion or encryption event by exporting it         from a clean snapshot to another virtual machine on a target cluster.<\/p>","href":"saas\/exporting_impacted_snapshots.html","attributes":{"data-id":"exporting_impacted_snapshots"},"menu":{"hasChildren":false},"tocID":"exporting_impacted_snapshots-d39307e53818","topics":[]},{"title":"Recovering impacted files and folders","shortdesc":"<p class=\"shortdesc\">Recover a specific set of files or folders impacted by a deletion or encryption         event, without recovering the entire object.<\/p>","href":"saas\/recovering_impacted_files.html","attributes":{"data-id":"recovering_impacted_files"},"menu":{"hasChildren":false},"tocID":"recovering_impacted_files-d39307e53829","topics":[]}]}};